(* [comment removed for export] *)
Lemma rng_mask_sh : forall RNG, rng_aimg_sh RNG -> rng RNG (shad ABIT_MASK) (nshad (128 + ABIT_MASK mod 8)).
Proof.
  intros RNG H. eapply rng_sub; [exact H| |];
  unfold shad, nshad, ASHOFF, ABIT_MASK; apply Z.leb_le; vm_compute; reflexivity.
Qed.

End CANSEC1.

(* [comment removed for export] *)
Ltac fdwA_acc_hint := bdtA_acc_hint.

(* [comment removed for export] *)
Ltac zify_lts K :=
  unfold bv_lts in K; rewrite ?land7_mod in K;
  rewrite !signed_lit_small64 in K by (Z.div_mod_to_equations; lia);
  zify_bool K.

(* [comment removed for export] *)
Ltac schk UH A :=
  let b := fresh "b" in let RDB := fresh "RDB" in let CK := fresh "CK" in let SR := fresh "SR" in
  let G := fresh "G" in let G' := fresh "G" in
  lazymatch goal with |- evtF _ _ _ (MS _ _ _ _ _ ?mg _) =>
    destruct (AF_fse_rd_base.chkB mg _ _ A (unpoisoned_appW _ _ mg _ _ UH ltac:(eassumption) ltac:(eassumption) ltac:(lia) ltac:(lia))
                ltac:(lia) ltac:(lia)) as (b & RDB & CK & SR) end;
  zstep; rewrite sxb_sval; clear RDB;
  zstep; if_cases G; zify_cond G;
  [ zstep; zstep; if_cases G'; zify_lts G'; [| exfalso; lia] | ].

(* [comment removed for export] *)
Ltac sjoinF rY J :=
  lazymatch goal with |- evtF ?segs ?RNG ?Q (MS ?R ?F _ ?fc ?rv ?m ?rom) =>
    let KJ := fresh "KJ" in
    assert (KJ : forall w : word, evtF segs RNG Q (MS (@bvmap_set 5 word (Z_to_bv 5 rY) w R) F (Z_to_bv 64 J) fc rv m rom));
    [ let w := fresh "w" in intros w; simp_regs | ]
  end.

(* [comment removed for export] *)
Ltac sjoin_close rY :=
  let G := fresh "G" in let G' := fresh "G" in
  zstep; if_cases G; zify_cond G;
  [ zstep; zstep; if_cases G'; zify_lts G'; [ lazymatch goal with KJ : forall w : word, _ |- _ => let v := reg_val rY in apply (KJ v) end
                                            | exfalso; lia ]
  | lazymatch goal with KJ : forall w : word, _ |- _ => let v := reg_val rY in apply (KJ v) end ].

(* [comment removed for export] *)
Ltac schkJ UH A rY J :=
  let b := fresh "b" in let RDB := fresh "RDB" in let CK := fresh "CK" in let SR := fresh "SR" in
  lazymatch goal with |- evtF _ _ _ (MS _ _ _ _ _ ?mg _) =>
    destruct (AF_fse_rd_base.chkB mg _ _ A (unpoisoned_appW _ _ mg _ _ UH ltac:(eassumption) ltac:(eassumption) ltac:(lia) ltac:(lia))
                ltac:(lia) ltac:(lia)) as (b & RDB & CK & SR) end;
  zstep; rewrite sxb_sval; clear RDB;
  sjoinF rY J; [| sjoin_close rY].

(* [comment removed for export] *)
Ltac hb_byteZ r :=
  zstep; zstep; zstep; brute_regZ 11%Z r 1 255 sm1;
  zstep; zstep; zstep; brute_regZ 11%Z r 1 255 sm2;
  zstep; zstep; brute_regZ 11%Z r 1 255 sm3;
  zstep; brute_regZ 11%Z r 1 255 nsm;
  zstep; zstep; zstep; zstep; zstep; brute_regZ 11%Z r 1 255 (fun r0 => pc_a (nsm r0));
  zstep; zstep; zstep; zstep; zstep; brute_regZ 11%Z r 1 255 (fun r0 => pc_b (pc_a (nsm r0)));
  zstep; zstep; brute_regZ 11%Z r 1 255 (fun r0 => pc_c (pc_b (pc_a (nsm r0))));
  zstep; zstep; zstep; zstep; zstep; brute_regZ 11%Z r 1 255 (fun r0 => pc_d (pc_c (pc_b (pc_a (nsm r0)))));
  zstep; brute_regZ 11%Z r 1 255 (fun r0 => 31 - Z.log2 r0).
